svg.script:
(function() {
  var params = new URLSearchParams(window.location.search);
  var model = params.get('model') || 'LLM';
  var score = parseInt(params.get('score')) || 0;
  var vectors = parseInt(params.get('vectors')) || 29;
  var langs = parseInt(params.get('langs')) || 5;
  var date = params.get('date') || new Date().toISOString().split('T')[0];

  // Determine grade
  var grade, color, label;
  if (score >= 90) { grade = 'A'; color = '#22c55e'; label = 'EXCELENTE'; }
  else if (score >= 80) { grade = 'B'; color = '#3b82f6'; label = 'BUENO'; }
  else if (score >= 70) { grade = 'C'; color = '#f59e0b'; label = 'ACEPTABLE'; }
  else if (score >= 60) { grade = 'D'; color = '#ea580c'; label = 'DEFICIENTE'; }
  else { grade = 'F'; color = '#ef4444'; label = 'RECHAZADO'; }

  var resisted = Math.round(vectors * score / 100);

  // Update elements
  document.getElementById('model').textContent = model;
  document.getElementById('grade').textContent = grade;
  document.getElementById('grade').setAttribute('fill', color);
  document.getElementById('scoreText').textContent = 
    'Score: ' + score + '/100 · ' + resisted + '/' + vectors + ' vectors · ' + langs + ' languages';

  // Update accent color
  var stops = document.querySelectorAll('#accent stop, #shield stop');
  stops.forEach(function(stop) {
    if (stop.style.stopColor === '#3b82f6') stop.style.stopColor = color;
    if (stop.style.stopColor === '#2563eb') stop.style.stopColor = color + '88';
  });

  // Update checkmark
  var circle = document.querySelector('circle');
  var check = document.querySelectorAll('path')[3]; // 4th path = checkmark
  if (circle) circle.setAttribute('stroke', color);
  if (check && grade !== 'F') {
    check.setAttribute('stroke', color);
  }

  // For grade F, change checkmark to X
  if (grade === 'F' && check) {
    check.setAttribute('d', 'M290 34 L310 54 M310 34 L290 54');
    check.setAttribute('stroke', '#ef4444');
  }
})();
